  CREATE OR REPLACE EDITIONABLE FUNCTION "PRIYANSHI"."CHECK_LOAN_ELIGIBILITY" (p                                                                                                                                                                                                                            
_cid NUMBER) RETURN VARCHAR2 AS                                                                                                                                                                                                                                                                             
    v_balance NUMBER;                                                                                                                                                                                                                                                                                       
BEGIN                                                                                                                                                                                                                                                                                                       
    SELECT NVL(SUM(balance),0) INTO v_balance FROM Account WHERE cid = p_cid;                                                                                                                                                                                                                               
    IF v_balance >= 100000 THEN                                                                                                                                                                                                                                                                             
        RETURN 'ELIGIBLE';                                                                                                                                                                                                                                                                                  
    ELSE                                                                                                                                                                                                                                                                                                    
        RETURN 'NOT ELIGIBLE';                                                                                                                                                                                                                                                                              
    END IF;                                                                                                                                                                                                                                                                                                 
EXCEPTION                                                                                                                                                                                                                                                                                                   
    WHEN NO_DATA_FOUND THEN                                                                                                                                                                                                                                                                                 
        RETURN 'NOT ELIGIBLE';                                                                                                                                                                                                                                                                              
END;                                                                                                                                                                                                                                                                                                        
/                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                            
  CREATE OR REPLACE EDITIONABLE FUNCTION "PRIYANSHI"."GET_BALANCE" (p_acc_id NUM                                                                                                                                                                                                                            
BER) RETURN NUMBER AS                                                                                                                                                                                                                                                                                       
    v_balance NUMBER;                                                                                                                                                                                                                                                                                       
BEGIN                                                                                                                                                                                                                                                                                                       
    SELECT balance INTO v_balance FROM Account WHERE acc_id = p_acc_id;                                                                                                                                                                                                                                     
    RETURN v_balance;                                                                                                                                                                                                                                                                                       
EXCEPTION                                                                                                                                                                                                                                                                                                   
    WHEN NO_DATA_FOUND THEN                                                                                                                                                                                                                                                                                 
        RETURN NULL;                                                                                                                                                                                                                                                                                        
END;                                                                                                                                                                                                                                                                                                        
/                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                            
