  CREATE OR REPLACE EDITIONABLE TRIGGER "PRIYANSHI"."TRG_ACCOUNT_BALANCE_CHECK"                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                            
BEFORE UPDATE OF balance ON Account                                                                                                                                                                                                                                                                         
FOR EACH ROW                                                                                                                                                                                                                                                                                                
BEGIN                                                                                                                                                                                                                                                                                                       
    IF :NEW.balance < 0 THEN                                                                                                                                                                                                                                                                                
        RAISE_APPLICATION_ERROR(-20006,'Account balance cannot be negative');                                                                                                                                                                                                                               
    END IF;                                                                                                                                                                                                                                                                                                 
END;                                                                                                                                                                                                                                                                                                        
