  CREATE OR REPLACE EDITIONABLE TRIGGER "PRIYANSHI"."TRG_TRANSACTION_BALANCE"                                                                                                                                                                                                                               
AFTER INSERT ON "TRANSACTION"                                                                                                                                                                                                                                                                               
FOR EACH ROW                                                                                                                                                                                                                                                                                                
BEGIN                                                                                                                                                                                                                                                                                                       
    IF UPPER(:NEW.type) IN ('DEPOSIT','CREDIT') THEN                                                                                                                                                                                                                                                        
        UPDATE Account SET balance = balance + :NEW.amount WHERE acc_id = :NEW.a                                                                                                                                                                                                                            
cc_id;                                                                                                                                                                                                                                                                                                      
    ELSIF UPPER(:NEW.type) IN ('WITHDRAW','WITHDRAWAL','DEBIT') THEN                                                                                                                                                                                                                                        
        UPDATE Account SET balance = balance - :NEW.amount WHERE acc_id = :NEW.a                                                                                                                                                                                                                            
cc_id;                                                                                                                                                                                                                                                                                                      
    END IF;                                                                                                                                                                                                                                                                                                 
END;                                                                                                                                                                                                                                                                                                        
